package ftboss.bossprobe;
import java.util.*;
import io.netty.buffer.Unpooled;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.RegistryFriendlyByteBuf;
import net.minecraft.network.protocol.game.ClientboundSetEntityDataPacket;
import net.minecraft.server.level.ServerLevel;
import net.farmingtales.ftboss.entity.*;
import net.farmingtales.ftboss.util.ManorFiveCombatRules.Skill;
import net.farmingtales.ftboss.animation.qingyicast.QingyiCastAccess;
import net.farmingtales.ftboss.body.BodyCueAccess;
import net.farmingtales.ftboss.zheergennightfall.NightfallAccess;
public final class BodyChainChecks {
    public static final List<String> checks=new ArrayList<>();
    public static final List<Map<String,Object>> samples=new ArrayList<>();
    private static final Map<UUID,CompoundTag> released=new HashMap<>();
    private static void require(boolean value,String name){if(!value)throw new AssertionError(name);checks.add(name);}
    private static CompoundTag q(EasterBossEntity actor){return ((QingyiCastAccess)actor).qingyiCastState().getCompound("native");}
    private static CompoundTag x(EasterBossEntity actor){return ((BodyCueAccess)actor).ftboss$bodyRead().getCompound("xuanlanBody");}
    private static CompoundTag z(EasterBossEntity actor){return ((NightfallAccess)actor).ftboss$nightfallRead().getCompound("ftboss_zheergen_remaining_body");}
    private static void mirror(EasterBossEntity actor,ServerLevel level){var values=actor.getEntityData().getNonDefaultValues();require(values!=null&&!values.isEmpty(),"ActualBodyNativeDataValues");RegistryFriendlyByteBuf buffer=new RegistryFriendlyByteBuf(Unpooled.buffer(),level.registryAccess());try{ClientboundSetEntityDataPacket.STREAM_CODEC.encode(buffer,new ClientboundSetEntityDataPacket(actor.getId(),values));var decoded=ClientboundSetEntityDataPacket.STREAM_CODEC.decode(buffer);require(buffer.readableBytes()==0&&decoded.id()==actor.getId(),"ActualBodyPacketCodecRoundtrip");EasterBossEntity mirror=FTEntities.EASTER_BOSS.get().create(level);require(mirror!=null,"ActualRegisteredBodyMirrorFactory");mirror.getEntityData().assignValues(decoded.packedItems());require(q(mirror).equals(q(actor))&&x(mirror).equals(x(actor))&&z(mirror).equals(z(actor))&&mirror.getSkillCue().equals(actor.getSkillCue()),"ActualBodyPacketAssignedToRegisteredServerMirror");mirror.discard();}finally{buffer.release();}}
    public static void verify(EasterBossEntity actor,Skill skill,int age,String phase,int pulse,boolean candidate,ServerLevel level){
        require(actor instanceof QingyiCastAccess&&actor instanceof BodyCueAccess&&actor instanceof NightfallAccess,"ExistingEffectiveBodyInterfacesPresent");CompoundTag q=q(actor),x=x(actor),z=z(actor);int variant=actor.getVariant();
        if(!candidate){require(q.isEmpty()&&x.isEmpty()&&z.isEmpty(),"ActualMissingOriginalBodyEntry:"+skill+":"+phase);return;}
        require(variant==5||q.isEmpty(),"OtherVariantsNoQingyiNativeState");require(variant==6||x.isEmpty(),"OtherVariantsNoXuanlanBodyState");require(variant==7||z.isEmpty(),"OtherVariantsNoShadowBodyState");
        if(variant==5){require(!q.isEmpty()&&q.getInt("track")== (skill==Skill.QINGYI_TIDE?3:skill==Skill.QINGYI_THUNDER?4:5),"OriginalQingyiNativeTrack:"+phase);require(q.getInt("duration")==actor.getChallengeDifficulty().acceleratedTicks(skill.windup),"OriginalQingyiNativeDuration:"+phase);int stage=phase.equals("start")?0:phase.equals("cancel")?2:1;require(q.getInt("stage")==stage,"OriginalQingyiNativeStage:"+phase);if(phase.equals("start"))require(q.getLong("start")==level.getGameTime()&&q.getDouble("origin")==0.42,"OriginalQingyiStartTimeAndOrigin");if(phase.equals("pulse"))require(q.getInt("pulses")==pulse+1&&!q.getBoolean("final")&&q.getLong("stop")==level.getGameTime(),"OriginalQingyiPulseState");if(phase.equals("finish"))require(q.getBoolean("final")&&q.getLong("finalAt")==level.getGameTime(),"OriginalQingyiFinalization");if(phase.equals("cancel"))require(q.getLong("stop")==level.getGameTime(),"OriginalQingyiCancellationTime");}
        if(variant==6){if(phase.equals("finish")||phase.equals("cancel")){require(x.isEmpty(),"OriginalXuanlanBodyClearedByActionEnd:"+phase);}else{require(x.getString("id").equals(skill==Skill.XUANLAN_RAIL?"rail":"ring")&&x.getBoolean("lockedAim"),"OriginalXuanlanBodyIdentityAndLockedAim");require(Math.abs(x.getDouble("aimYaw")+90.0)<0.000001&&x.getDouble("aimPitch")==0,"OriginalXuanlanBodyAim");if(phase.equals("start")){require(x.getLong("start")==level.getGameTime()&&x.getInt("windup")==Math.max(0,Math.min(200,skill.windup-age)),"OriginalXuanlanBodyWindup");CompoundTag cue=actor.getSkillCue();require(cue.getString("xuanlanNative").equals(skill.id())&&cue.getLong("start")==level.getGameTime()&&cue.getInt("duration")==skill.duration()-age&&cue.getInt("windup")==skill.windup-age&&cue.getInt("pulses")==skill.pulses&&cue.getInt("interval")==skill.interval,"OriginalXuanlanNativeCueTiming");require(cue.getDouble("x")== ((skill.shape==net.farmingtales.ftboss.util.ManorFiveCombatRules.Shape.BEAM||skill.shape==net.farmingtales.ftboss.util.ManorFiveCombatRules.Shape.WAVE||skill.shape==net.farmingtales.ftboss.util.ManorFiveCombatRules.Shape.CONE)?8.0:12.0)&&cue.getDouble("y")==320.0&&cue.getDouble("z")==8.0&&cue.getDouble("radius")==skill.radius&&cue.getDouble("directionX")==1.0&&cue.getDouble("directionZ")==0.0&&!cue.getBoolean("follow"),"OriginalXuanlanNativeCueGeometry:"+skill.shape+":"+cue);}}}
        if(variant==7){if(phase.equals("finish")){CompoundTag release=released.get(actor.getUUID());require(release!=null,"OriginalShadowReleasePreviouslyObserved");boolean live=level.getGameTime()-release.getLong("start")<release.getInt("duration");require(live?z.equals(release):z.isEmpty(),"OriginalShadowFinishRetainsOnlyLiveRelease");}else{String expected=phase.equals("start")?"charge":phase.equals("cancel")?"cancel":"release";require(z.getInt("schema")==1&&z.getString("id").equals(skill.id())&&z.getString("phase").equals(expected),"OriginalShadowBodySchemaAndPhase:"+phase);if(phase.equals("start"))require(z.getLong("start")==level.getGameTime()&&z.getInt("duration")==Math.max(1,Math.min(200,skill.windup-age)),"OriginalShadowChargeDuration");if(phase.equals("pulse")){require(z.getInt("duration")==Math.min(100,(skill.pulses-1)*skill.interval+14),"OriginalShadowReleaseDuration");if(pulse==0){require(z.getLong("start")==level.getGameTime(),"OriginalShadowFirstPulseReleases");released.put(actor.getUUID(),z.copy());}else require(z.equals(released.get(actor.getUUID())),"OriginalShadowLaterPulsesRetainRelease");}if(phase.equals("cancel"))require(z.getString("track").equals("charge")&&z.getInt("duration")==5&&z.getLong("start")==level.getGameTime()&&z.getDouble("frozen")>=0&&z.getDouble("frozen")<=1,"OriginalShadowCancellationCapturesCharge");}}
        if(variant==5||variant==6||variant==7){mirror(actor,level);samples.add(Map.of("variant",variant,"skill",skill.name(),"difficulty",actor.getChallengeDifficulty().name(),"phase",phase,"pulse",pulse,"qingyi",q.toString(),"xuanlan",x.toString(),"shadow",z.toString(),"skillCue",actor.getSkillCue().toString()));}
    }
}
